function renderCityBoard(){const city=$('city'),zoneTokens=(entries,zone)=>entries.filter(p=>p.zone===zone).map(p=>playerToken(p.player,p.pawn)).join(''),zones=entries=>`<div class="action-spaces">${[0,1,2,3].map((zone,i)=>`<span class="${i===1&&state.referencePlayers<4||i===2&&state.referencePlayers<3?'blocked':''} ${i===3?'infinite':''}">${i?[0,2,3,4][i]===4?'−4 <small>∞</small>':`−${[0,2,3,4][i]}`:''}${zoneTokens(entries,zone)}</span>`).join('')}</div>`,addAction=(name,body,extra='')=>{const button=document.createElement('button');button.className=`action-board ${extra}`;button.innerHTML=`<strong>${name}</strong>${body}`;button.onclick=()=>cityAction(name);city.append(button);};city.innerHTML='';addAction('Raccolto',zones(state.harvestPawns||[]));addAction('Produzione',zones(state.productionPawns||[]));const marketBoard=document.createElement('section');marketBoard.className='action-board market-board';marketBoard.innerHTML='<strong>Mercato</strong><div class="market-spaces"></div>';state.marketSlots.forEach((slot,index)=>{const button=document.createElement('button');button.className=`market-slot ${slot.occupied?'occupied':''}`;button.disabled=slot.occupied||state.ended||state.selected===null||waitingForLorenzo();button.innerHTML=`${iconizeResources(MARKET_BONUSES[slot.id]||slot.id)}${slot.occupiedBy?playerToken(slot.occupiedBy,slot.occupiedPawn):''}`;button.setAttribute('aria-label',`${slot.id}: ${MARKET_BONUSES[slot.id]||''}${slot.occupied?' · occupato':''}`);button.onclick=()=>{if(mutate(()=>market(state,index)))pendingDialog();};marketBoard.querySelector('.market-spaces').append(button);});city.append(marketBoard);const councilTokens=(state.councilPawns||[]).map((p,index)=>`<span class="council-placement"><small>${index+1}º</small>${playerToken(p.player,p.pawn)}</span>`).join('')||'<em>Nessun familiare piazzato</em>';addAction('Palazzo del Consiglio',`<div class="council-space"><div class="council-bonus"><span>${resourceIcon('moneta',1)}</span><b>+</b><span>${resourceIcon('favore',1)}</span></div><div class="council-order"><small>Ordine del prossimo round</small><div class="council-token-lane">${councilTokens}</div></div></div>`,'council-board');renderFaithTrack(city);}
function renderFaithTrack(city){const thresholds={3:0,4:1,5:2},markersAt=value=>{const markers=state.playerStates.map(player=>({name:player.name,color:player.color,value:player.resources.fede}));if(state.mode==='solo')markers.push({name:'Lorenzo',color:'#252525',value:state.solo.resources.fede});return markers.filter(marker=>Math.min(15,marker.value)===value).map(marker=>`<i class="faith-marker" style="--marker:${marker.color}" title="${marker.name}: ${marker.value} fede">${marker.name.slice(0,1).toUpperCase()}</i>`).join('')},excommunicationMarkers=tile=>state.playerStates.filter(player=>(player.activeExcommunications||[]).some(active=>active.id===tile.id)).map(player=>`<i class="faith-marker" style="--marker:${player.color}" title="${player.name} ha ricevuto questa scomunica">${player.name.slice(0,1).toUpperCase()}</i>`).join('');const board=document.createElement('section');board.className='faith-board';board.innerHTML=`<div class="faith-heading"><strong>Tracciato fede</strong><span>Difesa dalle scomuniche: 3 / 4 / 5</span></div><div class="faith-track">${FAITH_VP.map((points,value)=>{const exIndex=thresholds[value],tile=exIndex!==undefined?state.excommunications?.[exIndex]:null;return`<div class="faith-space ${tile?'excommunication-space':''}"><small>${points} PV</small><b>${value}${value===15?'+':''}</b>${tile?`<em title="${tile.effect}">S${exIndex+1}<span>${tile.name}</span></em>`:''}<div class="faith-markers">${markersAt(value)}</div></div>`}).join('')}</div><div class="faith-excommunications">${(state.excommunications||[]).map((tile,index)=>`<article><b>S${index+1} · soglia ${index+3}</b><span>${tile.name}</span><small>${tile.effect}</small><div class="excommunication-markers">${excommunicationMarkers(tile)}</div></article>`).join('')}</div>`;city.append(board);}
