function confirmAction(title,description,action,label){modal(`<h2>${title}</h2><p>${description}</p><div class="dialog-actions"><button id="cancel">Torna al tavolo</button><button class="primary" id="confirm">${label}</button></div>`);$('cancel').onclick=()=>dialog.close();$('confirm').onclick=()=>{action();dialog.close();};}
function completeAdvance(){mutate(()=>{const completedRound=state.round,councilPlacements=structuredClone(state.councilPawns||[]);advance(state);if(state.mode==='solo')soloEndRound(state,completedRound,councilPlacements);if(state.mode==='solo'&&[3,5].includes(state.round))soloNewEra(state);if(state.mode==='solo'&&state.ended)soloFinalScore(state);state.log.unshift(state.ended?'Partita conclusa: punteggio finale calcolato.':`Inizio turno ${state.round}: nuove carte e nuovo lancio dei dadi.`);});if(state.ended&&saveHighScore(state))toast('Risultato salvato negli Highscore.');dialog.close();if(state.ended)requestAnimationFrame(()=>document.getElementById('final-results').scrollIntoView({behavior:'smooth',block:'start'}));}
function afterVatican(){saveActivePlayer(state);const i=state.playerStates.findIndex(p=>!p.vaticanResolvedRounds.includes(state.round));if(i>=0){activatePlayer(state,i);viewedPlayerIndex=state.activePlayerIndex;render();openVatican();}else completeAdvance();}
function openVatican(){const status=vaticanStatus(state),active=state.playerStates[state.activePlayerIndex];if(active?.kind==='automa'){let result;if(mutate(()=>{result=automaDefendsVatican(state);state.log.unshift(`${active.name}: ${result.defend?'si difende dal Vaticano':'accetta la scomunica'}.`);}))afterVatican();return;}modal(`<span class="eyebrow">RAPPORTO IN VATICANO · ${state.playerStates[state.activePlayerIndex].name} · LIVELLO ${status.level}</span><h2>${status.tile.name}</h2><p>${status.tile.effect}</p><dl class="effects"><dt>Fede richiesta</dt><dd>${status.threshold}</dd><dt>Fede posseduta</dt><dd>${status.faith}</dd><dt>Punti difendendoti</dt><dd>${status.points}</dd></dl><p>Se ti difendi, ottieni i punti indicati e ritorni a 0 fede. Se non ti difendi, conservi la fede e la scomunica resta attiva per tutta la partita.</p><div class="dialog-actions"><button id="take-excommunication">Accetta la scomunica</button><button class="primary" id="defend-vatican" ${status.canDefend?'':'disabled'}>Difenditi</button></div>`);$('take-excommunication').onclick=()=>{if(mutate(()=>resolveVatican(state,false)))afterVatican();};$('defend-vatican').onclick=()=>{if(mutate(()=>resolveVatican(state,true)))afterVatican();};}
function next(){if(vaticanStatus(state)){openVatican();return;}confirmAction(state.round===6?'Concludere la partita?':'Passare al turno successivo?',`${4-state.used.length} familiari non impiegati. Le carte rimaste nelle torri verranno scartate.${state.round===6?' Verranno calcolati automaticamente Territori, Edifici, Personaggi, Imprese e premio militare.':''}`,completeAdvance,state.round===6?'Concludi':'Prosegui');}
 $('next-player').onclick=()=>{if(state.mode==='solo'){let result;mutate(()=>{result=soloTurn(state,cardImmediate);state.log.unshift(`Lorenzo: carta ${result.card.id}, dado ${result.die}.`);});if(result)toast(`Lorenzo ha tirato ${result.die}: azione principale ${result.target}.`);return;}const active=state.playerStates[state.activePlayerIndex];if(active.kind==='automa'){let report,automaIndex=state.activePlayerIndex;if(mutate(()=>{report=runAutomaTurn(state);state.lastActionSummary={title:`${report.player} · ${report.description}`,cards:[{name:'Strategia',effect:`Priorità ${report.strategy}`},...report.cardsGained.map(name=>({name,effect:'Carta acquisita'})),...report.leadersPlayed.map(name=>({name,effect:'Leader giocato'}))],changes:report.changes,hasPending:false};nextPlayer(state);})){viewedPlayerIndex=state.activePlayerIndex;toast(`${report.player}: ${report.description}.`);}return;}mutate(()=>{const player=nextPlayer(state);viewedPlayerIndex=state.activePlayerIndex;state.log.unshift(`Ora gioca ${player.name}.`);});};$('next').onclick=next;$('undo').onclick=()=>{if(history.length){state=history.pop();render();toast('Ultima modifica annullata.');}};
