function territoryInfo(c){const t=TERRITORIES[c.id];return `<dl class="effects"><dt>Costo della carta</dt><dd>Nessun costo in risorse; requisito militare in base alla posizione nel dominio.</dd><dt>Beneficio immediato</dt><dd>${describeEffects(t.immediate)}</dd><dt>Raccolto · valore minimo ${t.threshold}</dt><dd>${describeEffects(t.harvest)}</dd></dl>${t.note?`<p class="warning">${t.note}</p>`:''}`;}
function buildingInfo(c){const b=BUILDINGS[c.id];return `<dl class="effects"><dt>Costo</dt><dd>${describeBuildingCost(b)}</dd><dt>Beneficio immediato</dt><dd>${describeEffects(b.immediate)}</dd><dt>Attivazione produzione</dt><dd>${b.activation==='X'?'Valore X dell’azione':`Dado di valore ${b.activation} o superiore`}</dd><dt>Effetto</dt><dd>${describeEffects(b.production)}</dd></dl>${b.note?`<p class="warning">${b.note}</p>`:''}`;}
function characterInfo(c){const p=CHARACTERS[c.id];return `<dl class="effects"><dt>Costo</dt><dd>${describeCost(p.cost)}</dd><dt>Beneficio immediato</dt><dd>${describeEffects(p.immediate)}</dd><dt>Effetto permanente</dt><dd>${describeEffects(p.permanent)}</dd></dl>${p.note?`<p class="warning">${p.note}</p>`:''}`;}
function ventureInfo(c){const v=VENTURES[c.id],military=v.military?` oppure almeno ${v.military.required} punti militari, spendendone ${v.military.pay}`:'';return `<dl class="effects"><dt>Costo</dt><dd>${describeCost(v.cost)}${military}</dd><dt>Beneficio immediato</dt><dd>${describeEffects(v.immediate)}</dd><dt>Punteggio di fine partita</dt><dd>${describeEffects(v.endGame)}</dd></dl>${v.note?`<p class="warning">${v.note}</p>`:''}`;}
function detail(c,type,level){if(!TERRITORIES[c.id]&&!BUILDINGS[c.id]&&!CHARACTERS[c.id]&&!VENTURES[c.id]){oldDetail(c,type,level);return;}const territory=!!TERRITORIES[c.id],building=BUILDINGS[c.id],character=!!CHARACTERS[c.id],venture=VENTURES[c.id];const info=territory?territoryInfo(c):building?buildingInfo(c):character?characterInfo(c):ventureInfo(c);modal(`<div class="detail"><img src="${c.image}" alt="${c.name}"><div><span class="eyebrow">${c.type.toUpperCase()} · EPOCA ${c.era} · ${c.id}</span><h2>${c.name}</h2>${info}${type?`<p>Piano: valore ${[1,3,5,7][level]}. Costo, beneficio immediato e bonus del piano sono automatici.</p><button class="primary" id="take">Acquisisci carta</button>`:`<p>${territory?'Territorio nel dominio: si attiva con il raccolto.':building?'Edificio nel dominio: si attiva con la produzione.':character?'Personaggio nel dominio: il suo effetto permanente è attivo.':'Impresa nel dominio: il punteggio viene calcolato alla fine della partita.'}</p>`}</div></div>`);if(type){$('take').disabled=state.ended;$('take').onclick=()=>{const options=venture?ventureCostOptions(state,venture):[];if(building?.costOptions){modal(`<h2>Scegli come pagare</h2><p>${c.name}</p><div class="choice-list" id="building-pay"></div>`);building.costOptions.forEach((cost,i)=>{const b=document.createElement('button');b.textContent=describeCost(cost);b.onclick=()=>{if(mutate(()=>acquire(state,type,level,`building-${i}`))){continuePending();}};$('building-pay').append(b);});}else if(venture&&options.length>1){modal(`<h2>Scegli come pagare</h2><p>${c.name}</p><div class="choice-list" id="venture-pay"></div>`);options.forEach(o=>{const b=document.createElement('button');b.textContent=o.label;b.onclick=()=>{if(mutate(()=>acquire(state,type,level,o.kind))){continuePending();}};$('venture-pay').append(b);});}else if(mutate(()=>acquire(state,type,level,options[0]?.kind||'auto'))){continuePending();}};}}

function resourceMarketDialog(p){let cost=null,gains=[];modal(`<span class="eyebrow">ABILITÀ 1× · PARACELSO</span><h2>Scambia 1 risorsa per 2 risorse</h2><div class="paracelsus-market"><section><h3>Spendi 1</h3><div id="paracelsus-cost"></div></section><span class="trade-arrow">→</span><section><h3>Ottieni 2</h3><div id="paracelsus-gains"></div><small>Puoi scegliere due volte la stessa risorsa.</small></section></div><div class="dialog-actions"><button id="cancel-paracelsus">Rinuncia allo scambio</button><button class="primary" id="confirm-paracelsus" disabled>Conferma lo scambio</button></div>`);const redraw=()=>{const costBox=$('paracelsus-cost'),gainBox=$('paracelsus-gains');costBox.innerHTML='';gainBox.innerHTML='';for(const resource of p.resources){const costButton=document.createElement('button');costButton.className=cost===resource?'selected-choice':'';costButton.disabled=state.resources[resource]<1;costButton.innerHTML=`${resourceIcon(resource,1)}<small>Disponibili: ${state.resources[resource]}</small>`;costButton.onclick=()=>{cost=resource;redraw();};costBox.append(costButton);const count=gains.filter(item=>item===resource).length,gainButton=document.createElement('button');gainButton.className=count?'selected-choice':'';gainButton.innerHTML=`${resourceIcon(resource,1)}${count?`<b>×${count}</b>`:''}`;gainButton.onclick=()=>{if(count>=p.gain)gains=gains.filter(item=>item!==resource);else if(gains.length<p.gain)gains.push(resource);redraw();};gainBox.append(gainButton);}$('confirm-paracelsus').disabled=!cost||gains.length!==p.gain;};$('cancel-paracelsus').onclick=()=>{if(mutate(()=>resolvePending(state,'skip'))){continuePending();}};$('confirm-paracelsus').onclick=()=>{if(mutate(()=>resolvePending(state,{cost,gains}))){continuePending();}};redraw();}
function raffaelloDialog(p){
 let selected=null;
 const renderResources=resources=>Object.entries(resources).map(([resource,amount])=>resourceIcon(resource,amount)).join('');
 modal(`<span class="eyebrow">SCAMBIO · ${esc(p.source)}</span><h2>Scegli lo scambio</h2><div class="raffaello-trades" id="raffaello-trades"></div><div class="dialog-actions"><button id="cancel-raffaello">Rinuncia allo scambio</button><button class="primary" id="confirm-raffaello" disabled>Conferma lo scambio</button></div>`);
 const redraw=()=>{
  const box=$('raffaello-trades');box.innerHTML='';
  p.options.forEach((trade,index)=>{
   const usable=Object.entries(trade.cost).every(([resource,amount])=>state.resources[resource]>=amount);
   const button=document.createElement('button');
   button.className='raffaello-trade'+(selected===index?' selected-choice':'');
   button.disabled=!usable;
   button.innerHTML=`<span><small>SPENDI</small>${renderResources(trade.cost)}</span><b class="trade-arrow">→</b><span><small>OTTIENI</small>${renderResources(trade.resources)}</span>${usable?'':'<em>Risorse insufficienti</em>'}`;
   button.onclick=()=>{selected=index;redraw();};box.append(button);
  });
  $('confirm-raffaello').disabled=selected===null;
 };
  $('cancel-raffaello').onclick=()=>{if(mutate(()=>resolvePending(state,'skip'))){continuePending();}};
 $('confirm-raffaello').onclick=()=>{if(mutate(()=>resolvePending(state,selected))){continuePending();}};
 redraw();
}function pendingDialog(){
 const p=state.pending[0];if(!p)return;
 if(p.kind==='resourceMarket'){resourceMarketDialog(p);return;}if(p.kind==='chooseTrades'){if(dialog.open)dialog.close();viewedPlayerIndex=state.activePlayerIndex;render();requestAnimationFrame(()=>$('pending-fallback').scrollIntoView({behavior:'smooth',block:'center'}));return;}if(['virtualTower','bonusAction','activateTerritory','activateBuilding','repeatTrade'].includes(p.kind)){dialog.close();viewedPlayerIndex=state.activePlayerIndex;render();const actionTarget=p.kind==='virtualTower'?'tower-virtual-action':'virtual-action';requestAnimationFrame(() => $(actionTarget).scrollIntoView({behavior:'smooth',block:'center'}));return;}let options=p.kind==='privilege'?PRIVILEGES:p.options;if(p.kind==='distinctPrivileges')options=PRIVILEGES.filter((_,i)=>!p.chosen.includes(i));if(p.kind==='playLeaderFree')options=state.leaderHand;if(p.kind==='bonusAction')options=Array.from({length:state.resources.servitori+1},(_,i)=>i);if(p.kind==='resourceMarket')options=p.resources;if(p.kind==='activateTerritory')options=state.collection.filter(c=>c.type==='territori'&&TERRITORIES[c.id].threshold<=p.value);if(p.kind==='activateBuilding')options=state.collection.filter(c=>c.type==='edifici'&&(BUILDINGS[c.id].threshold==='X'||BUILDINGS[c.id].threshold<=p.value));if(p.kind==='copyCharacterImmediate')options=state.collection.filter(c=>c.type==='personaggi'&&c.id!=='personaggi-3-12');if(p.kind==='copyTerritory')options=state.collection.filter(c=>c.type==='territori'&&c.id!=='territori-2-10');if(p.kind==='trade')options=[p];if(p.kind==='repeatTrade')options=Array.from({length:p.maxUses},(_,i)=>i+1);if(p.kind==='marketBonus')options=state.marketSlots.filter(slot=>!slot.occupied);if(p.kind==='materialPenalty')options=['legno','pietra'];modal(`<span class="eyebrow">EFFETTO IN SOSPESO · ${state.pending.length}</span><h2>${p.source}</h2><p>${p.kind==='privilege'?'Scegli il privilegio del Consiglio.':p.kind==='distinctPrivileges'?`Scegli ${p.count} privilegi diversi (${p.chosen.length}/${p.count} scelti).`:p.kind==='playLeaderFree'?'Scegli un Leader dalla mano: verrà giocato ignorando i requisiti.':p.kind==='bonusAction'?`Attiva ora ${p.action==='production'?'una produzione':'un raccolto'} di valore ${p.value} più i bonus permanenti.`:p.kind==='resourceMarket'?(p.stage?`Scegli ${p.remaining} ${p.remaining===1?'risorsa':'risorse'} da ottenere.`:'Scegli la risorsa da spendere.'):p.kind==='activateTerritory'?`Scegli un Territorio da attivare con valore ${p.value}.`:p.kind==='activateBuilding'?`Scegli un Edificio da attivare con valore ${p.value}.`:p.kind==='copyCharacterImmediate'?'Scegli un altro Personaggio nel tuo dominio e applicane nuovamente l’effetto immediato.':p.kind==='manual'?p.text:p.kind==='materialPenalty'?'Scegli quale risorsa ridurre di 1.':p.kind==='copyTerritory'?'Scegli il Territorio di cui copiare l’effetto di raccolto.':p.kind==='repeatTrade'?`Scegli quante volte eseguire lo scambio, fino a ${p.maxUses} (valore della produzione).`:p.kind==='marketBonus'?'Scegli un bonus visibile del mercato dove non è ancora stato piazzato nessuno.':p.kind==='trade'?'Vuoi eseguire questo scambio?':'Scegli uno dei benefici.'}</p><div class="choice-list" id="effect-options"></div>`);if(p.kind==='manual'){$('effect-options').innerHTML='<button id="manual-effect">Segna come risolto manualmente</button>';$('manual-effect').onclick=()=>{if(mutate(()=>resolvePending(state,'manual'))){continuePending();}};}else{(options||[]).forEach((e,i)=>{const b=document.createElement('button');if(p.kind==='materialPenalty')b.textContent='Perdi 1 '+e;else if(p.kind==='activateTerritory')b.textContent=`${e.name}: ${describeEffects(TERRITORIES[e.id].harvest)}`;else if(p.kind==='resourceMarket')b.textContent=`${p.stage?'Ottieni':'Spendi'} 1 ${e}`;else if(p.kind==='activateBuilding')b.textContent=`${e.name}: ${describeEffects(BUILDINGS[e.id].production)}`;else if(p.kind==='copyCharacterImmediate')b.textContent=`${e.name}: ${describeEffects(CHARACTERS[e.id].immediate)}`;else if(p.kind==='copyTerritory')b.textContent=`${e.name}: ${describeEffects(TERRITORIES[e.id].harvest)}`;else if(p.kind==='repeatTrade')b.textContent=`${e} ${e===1?'volta':'volte'}`;else if(p.kind==='marketBonus')b.innerHTML=`<img src="assets/${e.id}.webp" alt="${e.id}" style="width:120px;display:block"><span>${e.id}</span>`;else if(p.kind==='playLeaderFree')b.textContent=e.name;else if(p.kind==='bonusAction')b.textContent=`Attiva ${p.action==='production'?'produzione':'raccolto'} di valore ${p.value+servantBonus(state,e)+characterActionBonus(state,p.action)} (${e} servitori)`;else b.textContent=describeEffect(e);b.onclick=()=>{const choice=p.kind==='repeatTrade'||p.kind==='materialPenalty'?e:i;if(mutate(()=>resolvePending(state,choice))){continuePending();}};$('effect-options').append(b);});if(['trade','chooseTrades','repeatTrade'].includes(p.kind)){const skip=document.createElement('button');skip.textContent='Non eseguire lo scambio';skip.onclick=()=>{if(mutate(()=>resolvePending(state,'skip'))){continuePending();}};$('effect-options').append(skip);}}}
function openHarvest(){modal('<h2>Lavoro / Raccolto</h2><p>Si attivano il Territorio prestampato e tutti i Territori con valore non superiore al valore dell’azione.</p><label for="harvest-zone">Zona di piazzamento</label><select id="harvest-zone"><option value="0">Spazio iniziale · nessuna penalità</option><option value="1">Spazio −2 · disponibile in 4 giocatori</option><option value="2">Spazio −3 · disponibile in 3–4 giocatori</option><option value="3">Spazio −4 · illimitato</option></select><div id="harvest-preview"></div><button class="primary" id="do-harvest">Esegui raccolto</button>');const effect=c=>describeEffects(c.printed?c.effects:TERRITORIES[c.id].harvest);const preview=()=>{try{const p=harvestPreview(state,Number($('harvest-zone').value));$('harvest-preview').innerHTML=`<h3>Valore ${p.value}</h3>${p.cards.map(c=>`<p><strong>${c.name}</strong>: ${effect(c)}</p>`).join('')||'<p>Nessun Territorio attivabile a questo valore.</p>'}`;$('do-harvest').disabled=state.ended||!!state.pending.length;}catch(e){$('harvest-preview').textContent=e.message;$('do-harvest').disabled=true;}};$('harvest-zone').onchange=preview;$('do-harvest').onclick=()=>{const zone=Number($('harvest-zone').value);if(mutate(()=>{const before={...state.resources},result=harvest(state,zone);state.lastActionSummary={title:`Raccolto di valore ${result.value}`,cards:result.cards.map(c=>({name:c.name,effect:effect(c)})),changes:resourceDelta(before,state.resources),hasPending:!!state.pending.length};})){continuePending();}};preview();}
function openProduction(){modal('<h2>Produzione</h2><p>Si attivano l’Edificio prestampato e tutti gli Edifici con valore non superiore al valore dell’azione.</p><label for="production-zone">Zona di piazzamento</label><select id="production-zone"><option value="0">Spazio iniziale · nessuna penalità</option><option value="1">Spazio −2 · disponibile in 4 giocatori</option><option value="2">Spazio −3 · disponibile in 3–4 giocatori</option><option value="3">Spazio −4 · illimitato</option></select><div id="production-preview"></div><button class="primary" id="do-production">Esegui produzione</button>');const effect=c=>describeEffects(c.printed?c.effects:BUILDINGS[c.id].production);const preview=()=>{try{const p=productionPreview(state,Number($('production-zone').value));$('production-preview').innerHTML=`<h3>Valore ${p.value}</h3>${p.cards.map(c=>`<p><strong>${c.name}</strong>: ${effect(c)}</p>`).join('')||'<p>Nessun Edificio attivabile a questo valore.</p>'}`;$('do-production').disabled=state.ended||!!state.pending.length;}catch(e){$('production-preview').textContent=e.message;$('do-production').disabled=true;}};$('production-zone').onchange=preview;$('do-production').onclick=()=>{const zone=Number($('production-zone').value);if(mutate(()=>{const before={...state.resources},result=production(state,zone);state.lastActionSummary={title:`Produzione di valore ${result.value}`,cards:result.cards.map(c=>({name:c.name,effect:effect(c)})),changes:resourceDelta(before,state.resources),hasPending:!!state.pending.length};})){continuePending();}};preview();}
$('pending-effects').onclick=pendingDialog;



























